            a, b = evaluate_formula(subformulas[0]), evaluate_formula(subformulas[2])
            if op == '&':
                return a and b
            elif op == '|':
                return a or b

    def compute_matroid_rank(formula):
        n = formula.count('(')
        rank_matrix = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n + 1):
